"""Summaries over collections of Entry objects."""


def summarise(entries) -> dict:
    """Return {"total": <count>, "per_channel": {<channel>: <count>}}."""
    total = 0
    per_channel: dict = {}
    for entry in entries:
        total += 1
        per_channel[entry.channel] = per_channel.get(entry.channel, 0) + 1
    return {"total": total, "per_channel": per_channel}

from tidelog import Entry, summarise


def test_summarise_three_entries_across_two_channels():
    entries = [
        Entry(ts="2026-11-02T22:00:00Z", channel=16, text="hello harbour"),
        Entry(ts="2026-11-02T22:05:00Z", channel=9, text="light fog"),
        Entry(ts="2026-11-02T22:10:00Z", channel=16, text="still clear"),
    ]
    result = summarise(entries)
    assert result["total"] == 3
    assert result["per_channel"] == {16: 2, 9: 1}
